"""长安杯2021 Crypto easyRSA 复现求解器。
已知 n,e,p_add_q,p_mul_q,c; 由 p+q 与 p*q 逐位确定 p,q 数字, 恢复私钥解密 c。
"""
def collect(m):
    res=[]
    while m:
        res.append(m%10); m//=10
    return res[::-1]
def solve(a,b):
    xa=(a-4)%10; xm=(b+4-2*a)%10
    ans=[]
    for x in range(48,58):
        for y in range(48,58):
            if (x+y)%10==xa and (x*y)%10==xm:
                ans.append((x-48,y-48))
    return ans
e=65537

p_add_q=10399034381787849923326924881454040531711492204619924608227265350044149907274051734345037676383421545973249148286183660679683016947030357640361405556516408
p_mul_q=6004903250672248020273453078045186428048881010508070095760634049430058892705564009054400328070528434060550830050010084328522605000400260581038846465000861
info1=collect(p_add_q)[1:]; info2=collect(p_mul_q)
ans_p=[0]; ans_q=[0]; cnt=1
for i in range(len(info1)-1,-1,-1):
    a=info1[i]; b=info2[i]; poss=solve(a,b)
    pp=[]; qq=[]
    for idx in range(len(ans_p)):
        pp0=ans_p[idx]; qq0=ans_q[idx]
        for x,y in poss:
            np_=pp0+x*(10**(cnt-1)); nq_=qq0+y*(10**(cnt-1))
            if (np_*nq_)%(10**cnt)==n%(10**cnt):
                pp.append(np_); qq.append(nq_)
    if pp: ans_p=pp; ans_q=qq
    cnt+=1

for p in ans_p:
    if p>1 and n%p==0:
        q=n//p
        d=pow(e,-1,(p-1)*(q-1))
        m=pow(c,d,n)
        flag=m.to_bytes((m.bit_length()+7)//8,"big").decode()
        if flag.startswith("flag"):
            print("VERIFIED changan2021_easyrsa:", flag); break
